    await page.locator("#street_address").fill("500 Castro Street");
    await page.locator("#city").fill("San Jose");
    await page.getByRole("button", { name: "Next: Payment →" }).click();
    await page.getByRole("button", { name: "← Back: Shipping" }).click();
    await expect(page.getByRole("textbox", { name: "Street Address" })).toHaveValue("500 Castro Street");
    await expect(page.getByRole("textbox", { name: "City" })).toHaveValue("San Jose");
    await page.getByRole("button", { name: "Next: Payment →" }).click();
    await page.getByRole("button", { name: "Next: Review →" }).click();
